/**
 * Origin CI checks — the Origin {@link CiCheckWriter} behind the shared check
 * lifecycle in `../checks.js`.
 *
 * Origin check runs are idempotent upserts keyed by `(repo, head SHA, suite
 * key, check key, externalId)`, so every write re-POSTs the full desired
 * state with a fresh `externalUpdatedAt`, and `resumeOriginCheck` needs only
 * those identity fields (no server id) to rebuild a handle after a restart.
 * The default `externalId` is per execution, so a re-run on the same head
 * posts a new attempt under the same key instead of rewriting the last one.
 *
 * Posting needs `repository:checks:write`: an `oit_…` installation token for
 * app channels, or a deployment service-account session (hosted v2 forks —
 * the `agent-serve` allowlist grants checks:write on team-owned namespaces).
 * See `createOriginClient` in `api.js`. Works with any client exposing
 * `request()` (`ctx.origin`, `createOriginClient()`), and is also reachable
 * as `ctx.origin.createCheck(...)`. API failures throw `OriginApiError`.
 */
import { randomUUID } from "node:crypto";
import { openCiCheck, resumeCiCheck, } from "../checks.js";
/**
 * Origin rejects the whole upsert when `output.title` exceeds 255 characters
 * or a body exceeds 65,535 UTF-8 bytes, so the writer caps rather than
 * risking a lost check write.
 */
const OUTPUT_TITLE_MAX_CHARS = 255;
const OUTPUT_BODY_MAX_BYTES = 65_000;
/** Truncate to at most `maxBytes` UTF-8 bytes without severing a character. */
function capUtf8Bytes(text, maxBytes) {
    const encoded = new TextEncoder().encode(text);
    if (encoded.length <= maxBytes) {
        return text;
    }
    // A non-fatal decode turns a trailing partial character into U+FFFD;
    // stripping it keeps the result valid (and re-encodable) under the cap.
    return new TextDecoder("utf-8").decode(encoded.subarray(0, maxBytes)).replace(/\uFFFD+$/, "");
}
function cappedOutput(output) {
    if (output === undefined) {
        return undefined;
    }
    return {
        title: output.title.slice(0, OUTPUT_TITLE_MAX_CHARS),
        summary: capUtf8Bytes(output.summary, OUTPUT_BODY_MAX_BYTES),
        ...(output.text === undefined
            ? {}
            : { text: capUtf8Bytes(output.text, OUTPUT_BODY_MAX_BYTES) }),
    };
}
/** Derive a stable check key from a display name, e.g. `cursor-security-review`. */
export function originCheckKeyFromName(name) {
    const slug = name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 100);
    return slug === "" ? "check" : slug;
}
/**
 * Origin writer: every write is a full keyed upsert. Tracks the last written
 * status so an output-only update cannot regress a running check to queued.
 */
function originCheckWriter(input) {
    const key = input.key ?? originCheckKeyFromName(input.name);
    const suiteKey = input.suite?.key ?? key;
    const externalId = input.externalId ??
        `agent-serve:${suiteKey}:${key}:${input.sha}:${input.executionId ?? randomUUID()}`;
    const path = `/v1/origin/repos/${encodeURIComponent(input.owner)}/${encodeURIComponent(input.repo)}/check-runs`;
    let lastStatus = input.status ?? "in_progress";
    return async (write) => {
        const status = write.status ?? (write.conclusion === undefined ? lastStatus : "completed");
        lastStatus = status;
        const response = await input.origin.request({
            method: "POST",
            path,
            body: {
                headSha: input.sha,
                checkSuite: {
                    key: suiteKey,
                    name: input.suite?.name ?? input.name,
                    externalId: `agent-serve:${suiteKey}`,
                    ...(input.suite?.detailsUrl === undefined ? {} : { detailsUrl: input.suite.detailsUrl }),
                },
                checkRun: {
                    key,
                    name: input.name,
                    status,
                    conclusion: write.conclusion,
                    // Origin only applies an upsert when this timestamp is at least as
                    // new as the stored check; timestamp every write when it is built.
                    externalUpdatedAt: new Date().toISOString(),
                    externalId,
                    startedAt: write.startedAt,
                    completedAt: write.completedAt,
                    detailsUrl: write.detailsUrl,
                    output: cappedOutput(write.output),
                },
            },
        });
        const id = response?.checkRun?.id;
        return typeof id === "string" ? { id } : undefined;
    };
}
/**
 * Create a CI check run on a commit and return a handle for later updates.
 *
 * ```ts
 * const check = await createOriginCheck({
 *   origin: ctx.origin,
 *   owner: ctx.repository.owner,
 *   repo: ctx.repository.name,
 *   name: "Cursor Security Review",
 *   sha: pr.headSha,
 *   detailsUrl: sessionUrl,
 *   output: { title: "Running…", summary: `[View session](${sessionUrl})` },
 * });
 * // …do the work…
 * await check.conclude({ conclusion: "success", output: { … } });
 * ```
 */
export function createOriginCheck(input) {
    return openCiCheck(originCheckWriter(input), input);
}
/**
 * Rebuild an {@link OriginCheck} handle for an existing check run (e.g.
 * after a process restart) from its upsert identity, including the
 * `executionId` (or explicit `externalId`) it was created with — no server
 * id needed. No API call is made until the first update.
 */
export function resumeOriginCheck(input) {
    return resumeCiCheck(originCheckWriter(input), input.id === undefined ? undefined : { id: input.id });
}
/**
 * Repo-bound checks adapter satisfying the shared {@link CiChecksClient}
 * contract — hand it to forge-agnostic check code when there is no channel
 * `ctx.origin` (e.g. CI entrypoints).
 */
export function bindOriginChecks(input) {
    return {
        createCheck: (check) => createOriginCheck({
            ...check,
            origin: input.origin,
            owner: input.owner,
            repo: input.repo,
        }),
    };
}
